12	// Spellings of the top-level field name as raw JSON key text.
13	const (
14		pluginParamsKey        = "pluginParams"
15		pluginParamsKeyEscaped = `\u0070luginParams` // JSON escape of "p"; decodes to pluginParams
16	)
17	
18	// pluginParamsField is one occurrence of the top-level pluginParams field:
19	// keyJSON is its raw JSON key text (allowing the p spelling) and
20	// valueJSON is the raw JSON value of that occurrence.
21	type pluginParamsField struct {
22		keyJSON   string
23		valueJSON string
24	}
25	
26	func pp(valueJSON string) pluginParamsField {
27		return pluginParamsField{keyJSON: pluginParamsKey, valueJSON: valueJSON}
28	}
29	
30	func ppEscaped(valueJSON string) pluginParamsField {
31		return pluginParamsField{keyJSON: pluginParamsKeyEscaped, valueJSON: valueJSON}
32	}
33	
34	// policyBodyWithParamFields builds a registration body carrying the given
35	// pluginParams occurrences in order, so a case can repeat the top-level field
36	// (including an escaped spelling of its name).
37	func policyBodyWithParamFields(ns, name, label string, fields ...pluginParamsField) string {
38		var b strings.Builder
39		fmt.Fprintf(&b, `{"namespace":%q,"name":%q,"label":%q,"rules":[{"direction":"ingress","action":"allow","ports":[80,80]}]`,
40			ns, name, label)
41		for _, f := range fields {
42			b.WriteString(`,"`)
43			b.WriteString(f.keyJSON)
44			b.WriteString(`":`)
45			b.WriteString(f.valueJSON)
46		}
47		b.WriteString("}")
48		return b.String()
49	}
50	
51	// Every occurrence of a repeated top-level pluginParams must be an object of
52	// string values. A null/scalar/array field value or an object carrying a
53	// non-string member is rejected even when a later legal object would overwrite
54	// it; field names match after JSON unescaping, so the literal and the
55	// \u0070-escaped spellings of pluginParams are the same field. On a brand-new identity the rejection
56	// writes nothing: namespace and label queries stay 404 NetPolicyNotFoundError
57	// and the first legal registration afterwards still takes order 1.
58	func TestPostNetPolicyRejectsIllegalRepeatedPluginParamsOnNewIdentity(t *testing.T) {
59		cases := map[string][]pluginParamsField{
60			"null member first, legal object last": {
61				pp(`{"mode": null}`), pp(`{"mode": "enforce"}`),
62			},
63			"legal object first, null member last": {
64				pp(`{"mode": "enforce"}`), pp(`{"mode": null}`),
65			},
66			"null field value first, legal object last": {
67				pp(`null`), pp(`{"mode": "enforce"}`),
68			},
69			"legal object first, null field value last": {
70				pp(`{"mode": "enforce"}`), pp(`null`),
71			},
72			"string field value then object": {
73				pp(`"enforce"`), pp(`{}`),
74			},
75			"number field value then object": {
76				pp(`1`), pp(`{}`),
77			},
78			"boolean field value then object": {
79				pp(`true`), pp(`{}`),
80			},
81			"array field value then object": {
82				pp(`["enforce"]`), pp(`{}`),
83			},
84			"object field value then object": {
85				pp(`{"nested": 1}`), pp(`{}`),
86			},
87			"number member first, legal object last": {
88				pp(`{"mode": 1}`), pp(`{"mode": "enforce"}`),
89			},
90			"boolean member first, legal object last": {
91				pp(`{"mode": true}`), pp(`{"mode": "enforce"}`),
92			},
93			"array member first, legal object last": {
94				pp(`{"mode": ["x"]}`), pp(`{"mode": "enforce"}`),
95			},
96			"object member first, legal object last": {
97				pp(`{"mode": {"x": 1}}`), pp(`{"mode": "enforce"}`),
98			},
99			"legal object first, number member last": {
100				pp(`{"mode": "enforce"}`), pp(`{"mode": 1}`),
101			},
102			"null member first, empty object last": {
103				pp(`{"mode": null}`), pp(`{}`),
104			},
105			"empty object first, null member last": {
106				pp(`{}`), pp(`{"mode": null}`),
107			},
108			"illegal middle occurrence among three": {
109				pp(`{}`), pp(`{"mode": null}`), pp(`{"mode": "enforce"}`),
110			},
111			"illegal first object carries an extra member": {
112				pp(`{"mode": null, "retries": "3"}`), pp(`{"mode": "enforce"}`),
113			},
114			"illegal last object, first carries other members": {
115				pp(`{"mode": "enforce", "retries": "3"}`), pp(`{"zone": null}`),
116			},
117			"escaped name null object first, literal legal last": {
118				ppEscaped(`{"mode": null}`), pp(`{"mode": "enforce"}`),
119			},
120			"literal null object first, escaped name legal last": {
121				pp(`{"mode": null}`), ppEscaped(`{"mode": "enforce"}`),
122			},
123			"literal legal first, escaped name null object last": {
124				pp(`{"mode": "enforce"}`), ppEscaped(`{"mode": null}`),
125			},
126		}
127		for name, fields := range cases {
128			t.Run(name, func(t *testing.T) {
129				router, _ := newTestRouter(t)
130				body := policyBodyWithParamFields("payments", "default-deny", "tier=backend", fields...)
131	
132				recorder := doRequest(router, http.MethodPost, "/v1/net-policies", body)
133				if recorder.Code != http.StatusBadRequest {
134					t.Fatalf("status = %d, want %d: %s", recorder.Code, http.StatusBadRequest, recorder.Body.String())
135				}
136				assertErrorCode(t, recorder, "InvalidNetPolicyInputError")
137				assertSafeErrorMessage(t, recorder)
138	
139				// A rejected new identity leaves no record behind.
140				for _, target := range []string{
141					"/v1/net-policies?namespace=payments",
142					"/v1/net-policies?label=tier%3Dbackend",
143				} {
144					miss := doRequest(router, http.MethodGet, target, "")
145					if miss.Code != http.StatusNotFound {
146						t.Fatalf("GET %s status = %d, want %d", target, miss.Code, http.StatusNotFound)
147					}
148					assertErrorCode(t, miss, "NetPolicyNotFoundError")
149				}
150	
151				// The rejected registration must not consume an order value.
152				good := policyBody("payments", "default-deny", "tier=backend", `{"mode": "enforce"}`)
153				created := doRequest(router, http.MethodPost, "/v1/net-policies", good)
154				if created.Code != http.StatusCreated {
155					t.Fatalf("valid status = %d, want %d: %s", created.Code, http.StatusCreated, created.Body.String())
156				}
157				var stored map[string]any
158				if err := json.Unmarshal(created.Body.Bytes(), &stored); err != nil {
159					t.Fatalf("decode: %v", err)
160				}
161				if stored["order"] != float64(1) {
162					t.Fatalf("order = %v, want 1 (rejected request must not consume an order)", stored["order"])
163				}
164			})
165		}
166	}
167	
168	// Re-posting an existing identity with an illegal repeated pluginParams is
169	// invalid input whether the final legal-looking object matches the stored
170	// content (never 200) or differs (never 409). The committed record, its order
171	// and its conflict flag stay untouched, and the next legal new identity keeps
172	// the sequence.
173	func TestPostNetPolicyIllegalRepeatedPluginParamsOnExistingIdentity(t *testing.T) {
174		cases := map[string][]pluginParamsField{
175			"illegal first, last object equal to stored": {
176				pp(`{"mode": null}`), pp(`{"mode": "enforce"}`),
177			},
178			"illegal first, last object differing stored": {
179				pp(`{"mode": null}`), pp(`{"mode": "audit"}`),
180			},
181			"null field value first, last object equal": {
182				pp(`null`), pp(`{"mode": "enforce"}`),
183			},
184			"illegal last object equal except for the hidden member": {
185				pp(`{"mode": "enforce", "retries": null}`), pp(`{"mode": "enforce"}`),
186			},
187			"escaped illegal occurrence, literal last equal": {
188				ppEscaped(`{"mode": null}`), pp(`{"mode": "enforce"}`),
189			},
190		}
191		for name, fields := range cases {
192			t.Run(name, func(t *testing.T) {
193				router, _ := newTestRouter(t)
194				// A clashing rule first so the seed record carries conflict=true,
195				// which every rejected retry must leave intact.
196				clash := policyWithRules("payments", "clash", "tier=backend",
197					`[{"direction":"ingress","action":"deny","ports":[80,80]}]`, `{}`)
198				if rec := doRequest(router, http.MethodPost, "/v1/net-policies", clash); rec.Code != http.StatusCreated {
199					t.Fatalf("clash seed status = %d: %s", rec.Code, rec.Body.String())
200				}
201				seed := doRequest(router, http.MethodPost, "/v1/net-policies",
202					policyBody("payments", "default-deny", "tier=backend", `{"mode": "enforce"}`))
203				if seed.Code != http.StatusCreated {
204					t.Fatalf("seed status = %d: %s", seed.Code, seed.Body.String())
205				}
206				var seedRecord map[string]any
207				if err := json.Unmarshal(seed.Body.Bytes(), &seedRecord); err != nil {
208					t.Fatalf("decode seed: %v", err)
209				}
210				if seedRecord["order"] != float64(2) || seedRecord["conflict"] != true {
211					t.Fatalf("seed metadata = order %v conflict %v, want order 2 conflict true",
212						seedRecord["order"], seedRecord["conflict"])
213				}
214	
215				retry := doRequest(router, http.MethodPost, "/v1/net-policies",
216					policyBodyWithParamFields("payments", "default-deny", "tier=backend", fields...))
217				if retry.Code != http.StatusBadRequest {
218					t.Fatalf("retry status = %d, want %d (never 200 or 409): %s",
219						retry.Code, http.StatusBadRequest, retry.Body.String())
220				}
221				assertErrorCode(t, retry, "InvalidNetPolicyInputError")
222				assertSafeErrorMessage(t, retry)
223	
224				items := listItems(t, router, "/v1/net-policies?namespace=payments")
225				if len(items) != 2 {
226					t.Fatalf("items = %v, want the two original records only", items)
227				}
228				var original map[string]any
229				for _, item := range items {
230					if item["name"] == "default-deny" {
231						original = item
232					}
233				}
234				if original == nil {
235					t.Fatalf("seed record missing after rejected retry: %v", items)
236				}
237				if !reflect.DeepEqual(original, seedRecord) {
238					t.Fatalf("record changed after rejected retry:\n got %v\nwant %v", original, seedRecord)
239				}
240	
241				// The rejected retries consumed no order: the next fresh identity
242				// continues at max order + 1.
243				next := doRequest(router, http.MethodPost, "/v1/net-policies",
244					policyBody("payments", "after-reject", "tier=backend", `{}`))
245				if next.Code != http.StatusCreated {
246					t.Fatalf("next status = %d, want %d: %s", next.Code, http.StatusCreated, next.Body.String())
247				}
248				var nextRecord map[string]any
249				json.Unmarshal(next.Body.Bytes(), &nextRecord)
250				if nextRecord["order"] != float64(3) {
251					t.Fatalf("next order = %v, want 3", nextRecord["order"])
252				}
253			})
254		}
255	}
256	
257	// When every repeated pluginParams occurrence is a legal string object the
258	// request stays valid: the LAST complete object is registered without merging
259	// members from earlier objects, an empty last object is saved as {}, and empty
260	// or whitespace-only strings in the last object are preserved verbatim. Both
261	// the registration response and GET queries expose only the final object.
262	func TestPostNetPolicyLegalRepeatedPluginParamsLastObjectWins(t *testing.T) {
263		cases := map[string]struct {
264			identity string
265			fields   []pluginParamsField
266			want     map[string]any
267		}{
268			"distinct members are not merged": {
269				"no-merge",
270				[]pluginParamsField{
271					pp(`{"mode": "audit", "zone": "east"}`),
272					pp(`{"mode": "enforce"}`),
273				},
274				map[string]any{"mode": "enforce"},
275			},
276			"empty object last saves empty object": {
277				"empty-last",
278				[]pluginParamsField{pp(`{"mode": "enforce"}`), pp(`{}`)},
279				map[string]any{},
280			},
281			"empty object first keeps later members": {
282				"empty-first",
283				[]pluginParamsField{pp(`{}`), pp(`{"mode": "enforce"}`)},
284				map[string]any{"mode": "enforce"},
285			},
286			"same members take last object values": {
287				"same-members",
288				[]pluginParamsField{
289					pp(`{"mode": "audit", "retries": "1"}`),
290					pp(`{"mode": "enforce", "retries": "5"}`),
291				},
292				map[string]any{"mode": "enforce", "retries": "5"},
293			},
294			"last object keeps empty and whitespace values": {
295				"special-values",
296				[]pluginParamsField{
297					pp(`{"mode": "enforce"}`),
298					pp(`{"mode": "  ", "zone": ""}`),
299				},
300				map[string]any{"mode": "  ", "zone": ""},
301			},
302			"escaped spelling of a legal occurrence": {
303				"escaped-key",
304				[]pluginParamsField{
305					ppEscaped(`{"zone": "east"}`),
306					pp(`{"mode": "enforce"}`),
307				},
308				map[string]any{"mode": "enforce"},
309			},
310		}
311		for name, tc := range cases {
312			t.Run(name, func(t *testing.T) {
313				router, _ := newTestRouter(t)
314				body := policyBodyWithParamFields("payments", tc.identity, "tier=backend", tc.fields...)
315				created := doRequest(router, http.MethodPost, "/v1/net-policies", body)
316				if created.Code != http.StatusCreated {
317					t.Fatalf("status = %d, want %d: %s", created.Code, http.StatusCreated, created.Body.String())
318				}
319				var resp map[string]any
320				if err := json.Unmarshal(created.Body.Bytes(), &resp); err != nil {
321					t.Fatalf("decode: %v", err)
322				}
323				if resp["order"] != float64(1) {
324					t.Fatalf("order = %v, want 1", resp["order"])
325				}
326				if !reflect.DeepEqual(resp["pluginParams"], tc.want) {
327					t.Fatalf("response pluginParams = %v, want %v (only the last object)", resp["pluginParams"], tc.want)
328				}
329	
330				items := listItems(t, router, "/v1/net-policies?namespace=payments")
331				if len(items) != 1 || !reflect.DeepEqual(items[0]["pluginParams"], tc.want) {
332					t.Fatalf("stored pluginParams = %v, want %v (only the last object)", items, tc.want)
333				}
334			})
335		}
336	}
337	
338	// An identity first registered from repeated legal objects behaves like any
339	// other record: a retry whose single object matches the final content returns
340	// 200 with the original record without consuming an order, different final
341	// content returns 409 NetPolicyConflictError, and the following fresh identity
342	// takes the next order. GET always shows only the last object's parameters.
343	func TestPostNetPolicyLegalRepeatedPluginParamsRetryConflictAndOrder(t *testing.T) {
344		router, _ := newTestRouter(t)
345		seedBody := policyBodyWithParamFields("payments", "default-deny", "tier=backend",
346			pp(`{"mode": "audit", "zone": "east"}`),
347			pp(`{"mode": "enforce"}`))
348		seed := doRequest(router, http.MethodPost, "/v1/net-policies", seedBody)
349		if seed.Code != http.StatusCreated {
350			t.Fatalf("seed status = %d: %s", seed.Code, seed.Body.String())
351		}
352		var seedRecord map[string]any
353		if err := json.Unmarshal(seed.Body.Bytes(), &seedRecord); err != nil {
354			t.Fatalf("decode seed: %v", err)
355		}
356		if !reflect.DeepEqual(seedRecord["pluginParams"], map[string]any{"mode": "enforce"}) {
357			t.Fatalf("seed pluginParams = %v, want only the last object {mode:enforce}", seedRecord["pluginParams"])
358		}
359	
360		// Same final content, spelled as a single object this time: 200 original.
361		same := doRequest(router, http.MethodPost, "/v1/net-policies",
362			policyBody("payments", "default-deny", "tier=backend", `{"mode": "enforce"}`))
363		if same.Code != http.StatusOK {
364			t.Fatalf("same-content retry status = %d, want %d: %s", same.Code, http.StatusOK, same.Body.String())
365		}
366		var sameRecord map[string]any
367		json.Unmarshal(same.Body.Bytes(), &sameRecord)
368		if !reflect.DeepEqual(sameRecord, seedRecord) {
369			t.Fatalf("retry record = %v, want original %v", sameRecord, seedRecord)
370		}
371	
372		// Different final content: 409, record untouched.
373		diff := doRequest(router, http.MethodPost, "/v1/net-policies",
374			policyBody("payments", "default-deny", "tier=backend", `{"mode": "audit"}`))
375		if diff.Code != http.StatusConflict {
376			t.Fatalf("different-content retry status = %d, want %d: %s", diff.Code, http.StatusConflict, diff.Body.String())
377		}
378		assertErrorCode(t, diff, "NetPolicyConflictError")
379	
380		items := listItems(t, router, "/v1/net-policies?namespace=payments")
381		if len(items) != 1 || !reflect.DeepEqual(items[0], seedRecord) {
382			t.Fatalf("items after retries = %v, want the unchanged seed %v", items, seedRecord)
383		}
384	
385		// Neither retry consumed an order: the next fresh identity takes order 2.
386		next := doRequest(router, http.MethodPost, "/v1/net-policies",
387			policyBodyWithParamFields("payments", "after", "tier=backend",
388				pp(`{"mode": "audit"}`), pp(`{}`)))
389		if next.Code != http.StatusCreated {
390			t.Fatalf("next status = %d: %s", next.Code, next.Body.String())
391		}
392		var nextRecord map[string]any
393		json.Unmarshal(next.Body.Bytes(), &nextRecord)
394		if nextRecord["order"] != float64(2) {
395			t.Fatalf("next order = %v, want 2", nextRecord["order"])
396		}
397		if !reflect.DeepEqual(nextRecord["pluginParams"], map[string]any{}) {
398			t.Fatalf("next pluginParams = %v, want empty last object {}", nextRecord["pluginParams"])
399		}
400	}
