244	// Empty store, same namespace and policy name: two content groups differing in
245	// one legal plugin string value race to register, each group including
246	// equivalent submissions with object members reordered, alongside requests
247	// carrying a null plugin member and queries issued during the burst. Exactly
248	// one 201 fixes the winning content; the winning group's other requests return
249	// 200 with that same record, the losing group all 409, and the null requests
250	// all 400. Queries are proven 404 against the empty store beforehand; during
251	// the burst every observation is either 404 or 200 carrying the single eventual
252	// winning record, but observing either state mid-flight is never itself a pass
253	// condition — all writes are allowed to finish before the next read is
254	// scheduled. Final state is checked through both filters and their intersection.
255	func TestConcurrentHTTPSameIdentityRace(t *testing.T) {
256		// Repeat against fresh databases: the winning group may differ per round.
257		for round := 0; round < 3; round++ {
258			t.Run(fmt.Sprintf("round%d", round), func(t *testing.T) {
259				server, _ := newConcurrentTestServer(t)
260				client := &http.Client{Timeout: clientTimeout}
261	
262				// One deadline covers every wait in the round: readers becoming
263				// ready, the whole write burst and reader shutdown.
264				deadline := time.NewTimer(roundBudget)
265				defer deadline.Stop()
266	
267				submissions := []struct {
268					kind string
269					body string
270				}{
271					{"A", raceBodyA},
272					{"A", raceBodyA},
273					{"A", raceBodyAReordered},
274					{"A", raceBodyAReordered},
275					{"B", raceBodyB},
276					{"B", raceBodyB},
277					{"B", raceBodyBReordered},
278					{"B", raceBodyBReordered},
279					{"null", raceBodyNullMember},
280					{"null", raceBodyNullMember},
281				}
282	
283				queryTargets := []string{
284					server.URL + "/v1/net-policies?namespace=payments",
285					server.URL + "/v1/net-policies?label=tier%3Dbackend",
286				}
287				intersectionTarget := server.URL + "/v1/net-policies?namespace=payments&label=tier%3Dbackend"
288	
289				// Deterministic pre-registration check: a query on the empty store
290				// is 404 with the published shape, for both filters. The concurrent
291				// readers below therefore never need to "happen to" catch 404.
292				for _, target := range queryTargets {
293					status, body, err := clientRequest(client, http.MethodGet, target, "")
294					if err != nil {
295						t.Fatalf("pre-registration GET %s failed: %v", target, err)
296					}
297					assertExactErrorBytes(t, status, body, http.StatusNotFound, "NetPolicyNotFoundError")
298				}
299	
300				// Readers run while the burst is in flight and stop only once every
301				// write has returned. stop runs on every exit path (including a
302				// fatal failure) so goroutines and the server are always released.
303				stopReaders := make(chan struct{})
304				var stopOnce sync.Once
305				stop := func() { stopOnce.Do(func() { close(stopReaders) }) }
306				t.Cleanup(stop)
307	
308				readerReady := make(chan struct{}, 4)
309				var readers sync.WaitGroup
310				observations := make(chan queryObservation, 65536)
311				for i := 0; i < 4; i++ {
312					readers.Add(1)
313					go func(id int) {
314						defer readers.Done()
315						ready := false
316						for attempts := 0; ; attempts++ {
317							select {
318							case <-stopReaders:
319								return
320							default:
321							}
322							target := queryTargets[(id+attempts)%len(queryTargets)]
323							status, body, err := clientRequest(client, http.MethodGet, target, "")
324							select {
325							case observations <- queryObservation{target: target, status: status, body: body, err: err}:
326							default:
327							}
328							if !ready {
329								ready = true
330								readerReady <- struct{}{}
331							}
332							runtime.Gosched()
333						}
334					}(i)
335				}
336	
337				// Release writers only after readers are already querying; whether
338				// a reader then catches the committed row is left to scheduling.
339				for ready := 0; ready < 2; ready++ {
340					select {
341					case <-readerReady:
342					case <-deadline.C:
343						t.Fatalf("round timed out before %d readers became ready\n%s",
344							2, formatQueryObservations(drainObservations(observations)))
345					}
346				}
347	
348				start := make(chan struct{})
349				var writers sync.WaitGroup
350				outcomes := make(chan postOutcome, len(submissions))
351				for _, submission := range submissions {
352					writers.Add(1)
353					go func(submission struct {
354						kind string
355						body string
356					}) {
357						defer writers.Done()
358						<-start
359						status, body, err := clientRequest(client, http.MethodPost,
360							server.URL+"/v1/net-policies", submission.body)
361						outcomes <- postOutcome{kind: submission.kind, status: status, body: body, err: err}
362					}(submission)
363				}
364	
365				close(start)
366				writersDone := make(chan struct{})
367				go func() {
368					writers.Wait()
369					close(writersDone)
370				}()
371				select {
372				case <-writersDone:
373				case <-deadline.C:
374					partial := drainOutcomes(outcomes)
375					t.Fatalf("round timed out waiting for the registration burst to finish\n%s\n%s",
376						formatPostOutcomes(partial),
377						formatQueryObservations(drainObservations(observations)))
378				}
379	
380				// All writes are allowed to complete before readers wind down:
381				// catching 200 during this window is best-effort, never required.
382				stop()
383				readersDone := make(chan struct{})
384				go func() {
385					readers.Wait()
386					close(readersDone)
387				}()
388				select {
389				case <-readersDone:
390				case <-deadline.C:
391					t.Fatalf("round timed out stopping readers\n%s\n%s",
392						formatPostOutcomes(drainOutcomes(outcomes)),
393						formatQueryObservations(drainObservations(observations)))
394				}
395	
396				results := drainOutcomes(outcomes)
397				raceObservations := drainObservations(observations)
398				if len(results) != len(submissions) {
399					t.Fatalf("collected %d POST results, want %d\n%s",
400						len(results), len(submissions), formatPostOutcomes(results))
401				}
402	
403				for _, result := range results {
404					if result.err != nil {
405						t.Fatalf("POST %s failed: %v\n%s", result.kind, result.err,
406							formatPostOutcomes(results))
407					}
408				}
409	
410				wantByGroup := map[string]map[string]any{
411					"A": wantRecord(t, raceBodyA, 1, false),
412					"B": wantRecord(t, raceBodyB, 1, false),
413				}
414	
415				// The single 201 response determines the winner; nothing here
416				// prescribes which content wins or relies on arrival order.
417				var winner map[string]any
418				winnerKind := ""
419				created, okStatus, rejected := 0, 0, 0
420				for _, result := range results {
421					switch result.status {
422					case http.StatusCreated:
423						created++
424						winner = decodeRecord(t, result.body)
425					case http.StatusOK:
426						okStatus++
427					case http.StatusConflict:
428					case http.StatusBadRequest:
429						rejected++
430					default:
431						t.Fatalf("unexpected POST status %d for kind %s: %s\n%s",
432							result.status, result.kind, string(result.body),
433							formatPostOutcomes(results))
434					}
435				}
436				if created != 1 {
437					t.Fatalf("created = %d responses, want exactly one 201\n%s",
438						created, formatPostOutcomes(results))
439				}
440				if mode, _ := winner["pluginParams"].(map[string]any)["mode"].(string); mode == "enforce" {
441					winnerKind = "A"
442				} else if mode == "audit" {
443					winnerKind = "B"
444				} else {
445					t.Fatalf("winning record pluginParams.mode = %v, want enforce or audit\nwinner=%v",
446						winner["pluginParams"], winner)
447				}
448				t.Logf("group %s (mode=%s) won the registration race", winnerKind,
449					winner["pluginParams"].(map[string]any)["mode"])
450				if !reflect.DeepEqual(winner, wantByGroup[winnerKind]) {
451					t.Fatalf("winning record = %v, want the full %s submission with order 1 conflict false",
452						winner, winnerKind)
453				}
454				if winner["order"] != float64(1) || winner["conflict"] != false {
455					t.Fatalf("winner order/conflict = %v/%v, want 1/false", winner["order"], winner["conflict"])
456				}
457	
458				winnerPeers, loserPeers := 0, 0
459				for _, result := range results {
460					switch result.kind {
461					case winnerKind:
462						if result.status == http.StatusCreated {
463							continue
464						}
465						// Remaining requests with the winning content are idempotent
466						// retries: 200 with the same original record.
467						if result.status != http.StatusOK {
468							t.Fatalf("winning group peer status = %d, want 200: %s\n%s",
469								result.status, string(result.body), formatPostOutcomes(results))
470						}
471						if got := decodeRecord(t, result.body); !reflect.DeepEqual(got, winner) {
472							t.Fatalf("200 record = %v, want the original winning record %v", got, winner)
473						}
474						winnerPeers++
475					case "null":
476						assertExactErrorBytes(t, result.status, result.body,
477							http.StatusBadRequest, "InvalidNetPolicyInputError")
478					default:
479						// Every request in the other group loses with 409.
480						assertExactErrorBytes(t, result.status, result.body,
481							http.StatusConflict, "NetPolicyConflictError")
482						loserPeers++
483					}
484				}
485				if winnerPeers != 3 {
486					t.Fatalf("winning group 200 peers = %d, want 3\n%s",
487						winnerPeers, formatPostOutcomes(results))
488				}
489				if loserPeers != 4 {
490					t.Fatalf("losing group 409 responses = %d, want 4\n%s",
491						loserPeers, formatPostOutcomes(results))
492				}
493				if rejected != 2 || okStatus != 3 {
494					t.Fatalf("status counts: 200=%d 400=%d, want 200=3 400=2\n%s",
495						okStatus, rejected, formatPostOutcomes(results))
496				}
497	
498				// Every query observed during the burst is legal: 404, or 200 with
499				// exactly one complete record — always the eventual winner, never a
500				// duplicate identity, losing content or a field mix. Whether either
501				// state was sampled is deliberately irrelevant; all writes may have
502				// finished before the next scheduled read.
503				for _, observation := range raceObservations {
504					if observation.err != nil {
505						t.Fatalf("GET %s failed: %v\n%s", observation.target, observation.err,
506							formatQueryObservations(raceObservations))
507					}
508					switch observation.status {
509					case http.StatusNotFound:
510						assertExactErrorBytes(t, observation.status, observation.body,
511							http.StatusNotFound, "NetPolicyNotFoundError")
512					case http.StatusOK:
513						var body struct {
514							Items []map[string]any `json:"items"`
515						}
516						if err := json.Unmarshal(observation.body, &body); err != nil {
517							t.Fatalf("decode items: %v\n%s", err,
518								formatQueryObservations(raceObservations))
519						}
520						if len(body.Items) != 1 {
521							t.Fatalf("GET %s returned %d items, want exactly one identity: %s\n%s",
522								observation.target, len(body.Items), string(observation.body),
523								formatQueryObservations(raceObservations))
524						}
525						if !reflect.DeepEqual(body.Items[0], winner) {
526							t.Fatalf("GET %s item = %v, want the complete winning record %v",
527								observation.target, body.Items[0], winner)
528						}
529					default:
530						t.Fatalf("GET during race status = %d for %s: %s\n%s",
531							observation.status, observation.target, string(observation.body),
532							formatQueryObservations(raceObservations))
533					}
534				}
535				t.Logf("observed %d queries during the burst (%d goroutines)",
536					len(raceObservations), 4)
537	
538				// Committed state after registration: both filters and their
539				// intersection return only the winner, identical in every submitted
540				// field plus order and conflict.
541				for _, target := range append(queryTargets, intersectionTarget) {
542					status, body, err := clientRequest(client, http.MethodGet, target, "")
543					if err != nil {
544						t.Fatalf("final GET %s: %v", target, err)
545					}
546					if status != http.StatusOK {
547						t.Fatalf("final GET %s status = %d: %s", target, status, string(body))
548					}
549					var listed struct {
550						Items []map[string]any `json:"items"`
551					}
552					if err := json.Unmarshal(body, &listed); err != nil {
553						t.Fatalf("decode final items: %v", err)
554					}
555					if len(listed.Items) != 1 || !reflect.DeepEqual(listed.Items[0], winner) {
556						t.Fatalf("final GET %s items = %v, want exactly %v", target, listed.Items, winner)
557					}
558				}
559	
560				// Failed 409s, 400s and 200 retries consumed no order: the next
561				// brand-new identity (egress, so no rule clash with the winner)
562				// takes order 2.
563				nextBody := singleRuleBody(raceNamespace, "after-race", raceLabel,
564					"egress", "allow", 53, 53, `{}`)
565				status, body, err := clientRequest(client, http.MethodPost,
566					server.URL+"/v1/net-policies", nextBody)
567				if err != nil {
568					t.Fatalf("POST next: %v", err)
569				}
570				if status != http.StatusCreated {
571					t.Fatalf("next status = %d, want 201: %s", status, string(body))
572				}
573				if got := decodeRecord(t, body); !reflect.DeepEqual(got, wantRecord(t, nextBody, 2, false)) {
574					t.Fatalf("next record = %v, want order 2 (lost and retried requests must not consume order)", got)
575				}
576			})
577		}
578	}
579	
580	// Two distinct policy names in one namespace sharing a label register at the
581	// same time: same direction, opposite actions, closed port intervals touching
582	// only at one endpoint. Both are 201; the one committed first gets order 1 and
583	// conflict=false, the other order 2 and conflict=true. Every filter returns
584	// both complete records in ascending order; retrying the original contents
585	// gives 200 without touching the flags, and a brand-new identity gets order 3.
586	func TestConcurrentHTTPTwoPoliciesConflictAndOrdering(t *testing.T) {
587		server, _ := newConcurrentTestServer(t)
588		client := &http.Client{Timeout: clientTimeout}
589	
590		// [80,100] and [100,200] intersect only at the closed endpoint 100.
591		denyBody := singleRuleBody("payments", "api-deny", "tier=backend",
592			"ingress", "deny", 80, 100, `{"mode": "enforce"}`)
593		allowBody := singleRuleBody("payments", "api-allow", "tier=backend",
594			"ingress", "allow", 100, 200, `{"mode": "enforce"}`)
595		bodyByName := map[string]string{"api-deny": denyBody, "api-allow": allowBody}
596	
597		start := make(chan struct{})
598		results := make(chan postOutcome, 2)
599		for _, body := range []string{denyBody, allowBody} {
600			go func(body string) {
601				<-start
602				status, raw, err := clientRequest(client, http.MethodPost,
603					server.URL+"/v1/net-policies", body)
604				results <- postOutcome{body: raw, status: status, err: err}
605			}(body)
606		}
607		close(start)
608	
609		storedByName := make(map[string]map[string]any, 2)
610		var first, second map[string]any
611		for range 2 {
612			result := <-results
613			if result.err != nil {
614				t.Fatalf("concurrent POST failed: %v", result.err)
615			}
616			if result.status != http.StatusCreated {
617				t.Fatalf("status = %d, want 201 for both distinct identities: %s",
618					result.status, string(result.body))
619			}
620			record := decodeRecord(t, result.body)
621			name, _ := record["name"].(string)
622			storedByName[name] = record
623			if first == nil || record["order"].(float64) < first["order"].(float64) {
624				second = first
625				first = record
626			} else {
627				second = record
628			}
629		}
630	
631		// Which name commits first is not prescribed; the returned order decides.
632		if first["order"] != float64(1) || first["conflict"] != false {
633			t.Fatalf("first committed = order %v conflict %v, want 1/false",
634				first["order"], first["conflict"])
635		}
636		if second["order"] != float64(2) || second["conflict"] != true {
637			t.Fatalf("second committed = order %v conflict %v, want 2/true",
638				second["order"], second["conflict"])
639		}
640		for order, record := range map[int64]map[string]any{1: first, 2: second} {
641			name, _ := record["name"].(string)
642			if _, known := bodyByName[name]; !known {
643				t.Fatalf("unexpected committed name %q", name)
644			}
645			want := wantRecord(t, bodyByName[name], order, order == 2)
646			if !reflect.DeepEqual(record, want) {
647				t.Fatalf("committed %s = %v, want the full submission with order %d and conflict=%v",
648					name, record, order, order == 2)
649			}
650		}
651	
652		want := []map[string]any{first, second}
653		for _, target := range []string{
654			server.URL + "/v1/net-policies?namespace=payments",
655			server.URL + "/v1/net-policies?label=tier%3Dbackend",
656			server.URL + "/v1/net-policies?namespace=payments&label=tier%3Dbackend",
657		} {
658			status, raw, err := clientRequest(client, http.MethodGet, target, "")
659			if err != nil {
660				t.Fatalf("GET %s: %v", target, err)
661			}
662			if status != http.StatusOK {
663				t.Fatalf("GET %s status = %d: %s", target, status, string(raw))
664			}
665			var body struct {
666				Items []map[string]any `json:"items"`
667			}
668			if err := json.Unmarshal(raw, &body); err != nil {
669				t.Fatalf("decode items: %v", err)
670			}
671			if !reflect.DeepEqual(body.Items, want) {
672				t.Fatalf("GET %s items = %v, want both complete records ascending by order",
673					target, body.Items)
674			}
675		}
676	
677		// Retry the original contents (one with reordered object members): 200 and
678		// the stored records, conflict flags included, come back untouched.
679		denyRetry := `{
680			"pluginParams": {"mode": "enforce"},
681			"rules": [{"ports": [80, 100], "action": "deny", "direction": "ingress"}],
682			"label": "tier=backend",
683			"name": "api-deny",
684			"namespace": "payments"
685		}`
686		for _, retry := range []struct {
687			name string
688			body string
689		}{
690			{"api-deny", denyRetry},
691			{"api-allow", allowBody},
692		} {
693			status, raw, err := clientRequest(client, http.MethodPost,
694				server.URL+"/v1/net-policies", retry.body)
695			if err != nil {
696				t.Fatalf("retry POST: %v", err)
697			}
698			if status != http.StatusOK {
699				t.Fatalf("retry status = %d, want 200: %s", status, string(raw))
700			}
701			if got := decodeRecord(t, raw); !reflect.DeepEqual(got, storedByName[retry.name]) {
702				t.Fatalf("retry record = %v, want unchanged original %v", got, storedByName[retry.name])
703			}
704		}
705	
706		// Retries consumed no order: a brand-new identity continues at order 3.
707		nextBody := singleRuleBody("payments", "api-next", "tier=backend",
708			"egress", "allow", 53, 53, `{}`)
709		status, raw, err := clientRequest(client, http.MethodPost,
710			server.URL+"/v1/net-policies", nextBody)
711		if err != nil {
712			t.Fatalf("POST next: %v", err)
713		}
714		if status != http.StatusCreated {
715			t.Fatalf("next status = %d, want 201: %s", status, string(raw))
716		}
717		if got := decodeRecord(t, raw); !reflect.DeepEqual(got, wantRecord(t, nextBody, 3, false)) {
718			t.Fatalf("next record = %v, want full submission with order 3", got)
719		}
720	}
721

