491			{"empty string value", "empty-val", `{"mode": ""}`, map[string]any{"mode": ""}},
492			{"whitespace value", "space-val", `{"mode": " \t "}`, map[string]any{"mode": " \t "}},
493			{"chinese value", "cn-val", `{"mode": "拦截"}`, map[string]any{"mode": "拦截"}},
494			{"literal null string", "literal-null", `{"mode": "null"}`, map[string]any{"mode": "null"}},
495			{"mixed empty and non-empty", "mixed", `{"a": "", "b": "enforce"}`, map[string]any{"a": "", "b": "enforce"}},
496		}
497		for _, tc := range cases {
498			t.Run(tc.name, func(t *testing.T) {
