500				body := policyBody("payments", tc.identity, "tier=backend", tc.paramsJSON)
501				created := doRequest(router, http.MethodPost, "/v1/net-policies", body)
502				if created.Code != http.StatusCreated {
503					t.Fatalf("status = %d, want %d: %s", created.Code, http.StatusCreated, created.Body.String())
504				}
505				var resp map[string]any
506				if err := json.Unmarshal(created.Body.Bytes(), &resp); err != nil {
507					t.Fatalf("decode: %v", err)
508				}
509				if !reflect.DeepEqual(resp["pluginParams"], tc.want) {
510					t.Fatalf("registration pluginParams = %v, want %v", resp["pluginParams"], tc.want)
