				`[{"direction":"ingress","action":"deny","ports":[80,80]}]`, `{}`)
			if rec := doRequest(router, http.MethodPost, "/v1/net-policies", clash); rec.Code != http.StatusCreated {
				t.Fatalf("clash seed status = %d: %s", rec.Code, rec.Body.String())
